mapper.select:
SELECT id, patient_no, name, gender, birth_date, identity_number, phone, active, created_at FROM patient
AND (name LIKE CONCAT('%', #{keyword}, '%') OR patient_no LIKE CONCAT('%', #{keyword}, '%') OR identity_number LIKE CONCAT('%', #{keyword}, '%'))
ORDER BY id DESC LIMIT #{size} OFFSET #{offset}

mapper.update:
UPDATE patient SET name=#{name}, gender=#{gender}, birth_date=#{birthDate}, phone=#{phone},
    address=#{address}, emergency_contact=#{emergencyContact}, emergency_phone=#{emergencyPhone},
    active=#{active}
WHERE id=#{id}

mapper.select:
SELECT a.id admission_id,a.admission_no,p.patient_no,p.name patient_name,p.gender,d.id department_id,d.name department_name,
  s.name attending_doctor_name,w.name ward_name,r.room_no,b.id bed_id,b.bed_no,a.admission_time,a.status
FROM admission a JOIN patient p ON p.id=a.patient_id JOIN department d ON d.id=a.department_id
JOIN staff s ON s.id=a.attending_doctor_id LEFT JOIN bed b ON b.id=a.current_bed_id
LEFT JOIN room r ON r.id=b.room_id LEFT JOIN ward w ON w.id=r.ward_id



        AND a.status IN ('IN_HOSPITAL','PENDING_DISCHARGE')
        AND a.status=#{status}

    AND a.department_id=#{departmentId}
    AND (p.name LIKE CONCAT('%',#{keyword},'%') OR p.patient_no LIKE CONCAT('%',#{keyword},'%') OR a.admission_no LIKE CONCAT('%',#{keyword},'%'))
    AND a.status IN ('IN_HOSPITAL','PENDING_DISCHARGE') AND TIMESTAMPDIFF(DAY,a.admission_time,UTC_TIMESTAMP(3)) >= #{longStayDays}
    AND a.status='PENDING_DISCHARGE' AND (
        EXISTS(SELECT 1 FROM medical_order mo WHERE mo.admission_id=a.id AND mo.status IN ('DRAFT','SUBMITTED','IN_PROGRESS'))
        OR EXISTS(SELECT 1 FROM v_admission_deposit_balance db WHERE db.admission_id=a.id AND db.available_balance<0)
    )

ORDER BY a.admission_time DESC,a.id DESC LIMIT #{size} OFFSET #{offset}

SELECT COUNT(*) FROM admission a JOIN patient p ON p.id=a.patient_id JOIN department d ON d.id=a.department_id
        JOIN staff s ON s.id=a.attending_doctor_id LEFT JOIN bed b ON b.id=a.current_bed_id
        LEFT JOIN room r ON r.id=b.room_id LEFT JOIN ward w ON w.id=r.ward_id 


                AND a.status IN ('IN_HOSPITAL','PENDING_DISCHARGE')
                AND a.status=#{status}

            AND a.department_id=#{departmentId}
            AND (p.name LIKE CONCAT('%',#{keyword},'%') OR p.patient_no LIKE CONCAT('%',#{keyword},'%') OR a.admission_no LIKE CONCAT('%',#{keyword},'%'))
            AND a.status IN ('IN_HOSPITAL','PENDING_DISCHARGE') AND TIMESTAMPDIFF(DAY,a.admission_time,UTC_TIMESTAMP(3)) >= #{longStayDays}
            AND a.status='PENDING_DISCHARGE' AND (
                EXISTS(SELECT 1 FROM medical_order mo WHERE mo.admission_id=a.id AND mo.status IN ('DRAFT','SUBMITTED','IN_PROGRESS'))
                OR EXISTS(SELECT 1 FROM v_admission_deposit_balance db WHERE db.admission_id=a.id AND db.available_balance<0)
            )

SELECT s.id, s.staff_no, s.name, s.staff_type, s.department_id, d.name department_name, s.active
FROM staff s LEFT JOIN department d ON d.id=s.department_id

    s.staff_type=#{staffType}
    AND s.department_id=#{departmentId}

ORDER BY s.staff_no

